const incidentType = ($('Entrada (tool: registrar_siniestro)').item.json.incident_type || '').toLowerCase();
const checklists = {
  auto: ['Fotos del vehículo (los 4 ángulos + daño)', 'Cédula de identidad', 'Licencia de conducir', 'Denuncia policial si hubo choque con terceros', 'Certificado médico si hay lesionados'],
  moto: ['Fotos de la moto (los 4 ángulos + daño)', 'Cédula de identidad', 'Licencia de conducir', 'Denuncia policial si aplica'],
  salud: ['Informe médico', 'Facturas/recibos originales', 'Cédula de identidad', 'Historia clínica si la solicita la aseguradora'],
  hogar: ['Fotos del daño', 'Cédula de identidad', 'Denuncia policial si fue robo', 'Presupuesto de reparación si lo tiene'],
  default: ['Cédula de identidad', 'Fotos o evidencia del incidente', 'Cualquier documento oficial relacionado (denuncia, informe, factura)']
};
let key = 'default';
if (incidentType.includes('moto')) key = 'moto';
else if (incidentType.includes('auto') || incidentType.includes('carro') || incidentType.includes('vehic')) key = 'auto';
else if (incidentType.includes('salud') || incidentType.includes('medic') || incidentType.includes('hospital')) key = 'salud';
else if (incidentType.includes('hogar') || incidentType.includes('casa') || incidentType.includes('robo')) key = 'hogar';
return [{ json: { checklist: checklists[key] } }];

