insert into public.claims (policy_id, contact_id, conversation_id, incident_at, incident_type, description, location, severity, required_docs, status)
select $2, c.id, $3, nullif($4,'')::timestamptz, $5, $6, $7, $8, $9::jsonb, 'reported'
from public.contacts c where c.phone = regexp_replace($1, '\D', '', 'g')
returning id, severity;
